sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float speed;
uniform float intensity;
uniform float seed;
float hash21(float2 p)
{
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001 || speed <= 0.0 || intensity <= 0.0) return c;
    float f = time * speed;
    float n = floor(f);
    float ramp = 0.15;
    float t = clamp((f - n - (1.0 - ramp)) / ramp, 0.0, 1.0);
    float r = mix(hash21(float2(mod(n, 4096.0), seed)), hash21(float2(mod(n + 1.0, 4096.0), seed)), t);
    float keep = clamp(1.0 - intensity * r, 0.0, 1.0);
    return c * half(keep);
}
